callGraph.callee:
reversed.map((note, i) => {
        // Reflect slot across the 16-step bar:
        const origSlot = antecedent[antecedent.length - 1 - i]?.slot ?? 0
        const slot = Math.max(0, Math.min(14, 16 - (origSlot + 4)))
        return {
          slot,
          lane: note.lane,
          holdSteps: note.holdSteps,
        }
      }).sort
